#!/usr/bin/env bash
S=$HOME/hugegraph-validation; V=113XgXE6D75j9n5evN6ecfkpb15bJNVJt3
SSH="ssh -n -o BatchMode=yes seba@192.168.80.235"; O=$S/results/pr-3184-sortkeys; mkdir -p $O
echo "== $(date +%T) load hstore (master dists, wipe)"; bash $S/cluster/idx_run_variant.sh sk3184b sk4-noindex 5000000 2>&1 | grep -E "RESULT|data|done" | cut -c1-120
echo "== $(date +%T) load rocksdb oracle"; $SSH 'HG_PORT=8081 python3 -u ~/idx_bench.py sk4-noindex 5000000 4 500 100000 /tmp/rd.json 2>&1 | grep -E "RESULT|Traceback" | cut -c1-120'
echo "== $(date +%T) probes on master"; $SSH "python3 ~/sk_shapes.py 8080 master-hstore $V; python3 ~/sk_shapes.py 8081 master-rocksdb $V" > $O/master.jsonl 2>&1
echo "== $(date +%T) swap to pr3184"; $SSH 'export JAVA_HOME=$HOME/tools/jdk11 PATH=$HOME/tools/jdk11/bin:/usr/bin:/bin:/usr/sbin; M=~/hg-master/hugegraph-server; P=~/hg-pr3184/hugegraph-server; (cd $M/dist-master-hstore && ./bin/stop-hugegraph.sh) >/dev/null 2>&1; (cd $M/dist-master-rocksdb && ./bin/stop-hugegraph.sh) >/dev/null 2>&1; sleep 4; for p in 8080 8081 8182 8183; do Q=$(ss -tlnp 2>/dev/null | grep ":$p " | grep -o "pid=[0-9]*" | head -1 | cut -d= -f2); [ -n "$Q" ] && kill -9 $Q; done; sleep 2; rm -rf $P/dist-pr3184-rocksdb/rocksdb-data && cp -r $M/dist-master-rocksdb/rocksdb-data $P/dist-pr3184-rocksdb/rocksdb-data; for D in $P/dist-pr3184-hstore $P/dist-pr3184-rocksdb; do (cd $D && rm -f bin/pid && ./bin/start-hugegraph.sh) >/dev/null 2>&1; done; for i in $(seq 1 40); do curl -sf http://127.0.0.1:8080/graphspaces/DEFAULT/graphs/hugegraph/schema/propertykeys >/dev/null && curl -sf http://127.0.0.1:8081/graphspaces/DEFAULT/graphs/hugegraph/schema/propertykeys >/dev/null && break; sleep 3; done; for p in 8080 8081; do curl -s -m 20 "http://127.0.0.1:$p/graphspaces/DEFAULT/graphs/hugegraph/graph/vertices?label=addr&limit=1" >/dev/null; done; echo "jars: hstore=$(md5sum $P/dist-pr3184-hstore/lib/hugegraph-hstore-*.jar | cut -c1-8) core=$(md5sum $P/dist-pr3184-hstore/lib/hugegraph-core-*.jar | cut -c1-8)"'
echo "== $(date +%T) probes on pr3184"; $SSH "python3 ~/sk_shapes.py 8080 pr3184-hstore $V; python3 ~/sk_shapes.py 8081 pr3184-rocksdb $V" > $O/pr3184.jsonl 2>&1
echo "== $(date +%T) done"
